#!/usr/bin/env python3
"""Generate resources for applicability messages without changing configuration logic."""
import hashlib
import json
from pathlib import Path
from xml.sax.saxutils import escape
root = Path(__file__).resolve().parents[1]
data = json.loads((root / 'tools/control-reason-translations.json').read_text())
entries = [(pt, data[pt], 'control_reason_' + hashlib.sha1(pt.encode()).hexdigest()[:12]) for pt in sorted(data)]
for folder, col in [('values', 1), ('values-pt-rBR', 0)]:
    lines = ['<?xml version="1.0" encoding="utf-8"?>', '<resources>']
    for e in entries:
        lines.append(f'    <string name="{e[2]}">{escape(e[col]).replace(chr(39), chr(92) + chr(39))}</string>')
    lines.append('</resources>')
    (root / f'app/src/main/res/{folder}/control_reasons.xml').write_text('\n'.join(lines) + '\n')
lines = ['package io.github.igorcv88.oneuiliquidglass.ui;', '', 'import android.content.Context;', 'import io.github.igorcv88.oneuiliquidglass.R;', 'import io.github.igorcv88.oneuiliquidglass.config.Controls;', '', '/** Generated by tools/generate-control-reasons.py. */', 'final class ControlReasons {', '    static String text(Context context, String reason) {', '        if (reason == null || reason.isEmpty()) return reason;', '        switch (reason) {']
for pt, en, name in entries:
    lines.append(f'            case {json.dumps(pt, ensure_ascii=False)}: return context.getString(R.string.{name});')
lines += ['            default: break;', '        }', '        for (Controls.Surface surface : Controls.Surface.values()) {', '            if (reason.equals("O vidro está desligado em " + surface.label))', '                return context.getString(R.string.control_surface_off, HomePage.surfaceLabel(context, surface));', '            for (java.util.Map.Entry<String, String> layer : Controls.layers(surface).entrySet())', '                if (reason.equals("A camada " + layer.getValue() + " está desligada"))', '                    return context.getString(R.string.control_layer_off, UiLabels.layer(context, layer.getKey()));', '        }', '        return reason;', '    }', '    private ControlReasons() {}', '}', '']
(root / 'app/src/main/java/io/github/igorcv88/oneuiliquidglass/ui/ControlReasons.java').write_text('\n'.join(lines))
